sys_variable_value.value:
(function execute(inputs, outputs) {
    var jdArch = new x_snc_aegis.AEGISJDArchitect();
    var jdText = '';
    var source = 'Now Assist GenAI';

    // 1. Check for GenAI skill output from Node 1
    if (inputs.skill_response && inputs.skill_response.trim().length > 50) {
        jdText = inputs.skill_response.trim();
        gs.info('[AEGIS-JD-AI] Using GenAI drafted JD for requisition: ' + inputs.requisition_sys_id);
    } else {
        // Deterministic High-Reliability Fallback Template via SI-3
        source = 'Deterministic Template (SI-3 Fallback)';
        jdText = '<h2>' + inputs.role_title + '</h2>' +
            '<h3>1. Role Summary</h3><p>We are seeking a talented ' + inputs.level + ' ' +
            inputs.role_title + ' to join our ' + inputs.department + ' team, driving innovative solutions with transparent and governed standards.</p>' +
            '<h3>2. Key Responsibilities</h3><ul>' +
            '<li>Design, build, and maintain high-quality, scalable services within ' + inputs.department + '.</li>' +
            '<li>Collaborate across cross-functional teams to deliver business-critical initiatives on schedule.</li>' +
            '<li>Drive operational excellence, code reviews, and adherence to security and compliance best practices.</li>' +
            '<li>Continuously optimize team performance and mentor junior team members.</li>' +
            '</ul>' +
            '<h3>3. Required Skills & Qualifications</h3><p>' + inputs.required_skills + '</p>' +
            '<h3>4. Nice to Have Skills</h3><p>' + (inputs.nice_to_have_skills || 'None specified') + '</p>' +
            '<h3>5. What We Offer</h3><p>Competitive compensation, clear career advancement pathways, continuous learning opportunities, and an inclusive work environment.</p>';
        gs.info('[AEGIS-JD-AI] GenAI offline or empty; applied deterministic fallback for: ' + inputs.requisition_sys_id);
    }

    // 2. Algorithmic Bias Scanning via SI-3 (Governance Enforcement)
    var biasCheck = jdArch.checkBiasedLanguage(jdText);
    outputs.bias_status = biasCheck.hasBias ? 'FLAGGED (' + biasCheck.flaggedTerms.join(', ') + ')' : 'PASSED';
    outputs.jd_source = source;

    // 3. Save Draft JD Record
    var jdSysId = jdArch.saveJD(inputs.requisition_sys_id, jdText, inputs.requested_by);
    outputs.jd_sys_id = jdSysId;
})(inputs, outputs);

